texts.text:
"""Japanese and Korean generation check for broken characters.

A checkpoint whose gate/up scales disagree was reported to garble multibyte
text (vLLM #54150). The pinned NVIDIA checkpoint is not affected, so this is a
monitor, not a fix: it asks for long answers and counts replacement characters,
lone surrogates and control characters in both the answer and the reasoning.
A short answer or one in another language proves nothing, so it never passes.
"""

import unicodedata

MIN_CHARACTERS = 400  # The length the prompts ask for.
PROMPTS = {
    "ja": (
        "日本の四季それぞれについて、気候の特徴と代表的な行事を、"
        "400文字以上の日本語の文章で説明してください。箇条書きは使わないでください。"
    ),
    "ko": (
        "한국의 사계절 각각에 대해 기후의 특징과 대표적인 행사를 "
        "400자 이상의 한국어 문장으로 설명해 주세요. 글머리 기호는 사용하지 마세요."
    ),
}
SCRIPTS = {
    "ja": ((0x3040, 0x30FF), (0x4E00, 0x9FFF)),  # Kana and CJK ideographs
    "ko": ((0xAC00, 0xD7A3), (0x1100, 0x11FF), (0x3130, 0x318F)),  # Hangul
}

def count_invalid_text(text):
    counts = {"replacement": 0, "lone_surrogate": 0, "control": 0}
    for character in text:
        code = ord(character)
        if character == "\N{REPLACEMENT CHARACTER}":
            counts["replacement"] += 1
        elif 0xD800 <= code <= 0xDFFF:
            counts["lone_surrogate"] += 1
        elif unicodedata.category(character) == "Cc" and character not in "\n\r\t":
            counts["control"] += 1
    return counts

def script_share(text, language):
    characters = [c for c in text if not c.isspace()]
    if not characters:
        return 0.0
    inside = sum(
        any(low <= ord(c) <= high for low, high in SCRIPTS[language])
        for c in characters
    )
    return inside / len(characters)

def judge(language, result):
    """One run's verdict: pass, fail, or inconclusive (never a silent pass)."""
    row = {"language": language}
    if isinstance(result, Exception):
        return {**row, "verdict": "inconclusive", "error": type(result).__name__}
    choice = result["choices"][0]
    content = choice["message"].get("content") or ""
    reasoning = choice["message"].get("reasoning") or ""
    row.update(
        finish_reason=choice["finish_reason"],
        truncated=choice["finish_reason"] == "length",
        characters=len(content),
        script_share=round(script_share(content, language), 3),
        content_invalid=count_invalid_text(content),
        reasoning_invalid=count_invalid_text(reasoning),
    )
    if any(row["content_invalid"].values()) or any(row["reasoning_invalid"].values()):
        row["verdict"] = "fail"
    elif len(content) < MIN_CHARACTERS or row["script_share"] <= 0.5:
        row["verdict"] = "inconclusive"
    else:
        row["verdict"] = "pass"
    row["content"], row["reasoning"] = content, reasoning
    return row

def run(ask, repeats=3, sampling=None):
    """Ask each prompt repeats times at temperature 0; never raise on answers.

    ``sampling`` ({temperature, top_p, seed}) counts broken characters in
    sampled answers instead: run i draws with seed + i, so repeats are distinct
    draws, and the record names the settings.
    """
    if sampling is not None and not (
        sampling.get("temperature", 0) > 0
        and 0 < sampling.get("top_p", 0) <= 1
        and isinstance(sampling.get("seed"), int)
    ):
        raise ValueError("Sampling needs temperature > 0, 0 < top_p <= 1 and a seed")
    rows = []
    for language, prompt in PROMPTS.items():
        for _ in range(repeats):
            request = {
                "messages": [{"role": "user", "content": prompt}],
                "temperature": 0,
            }
            if sampling is not None:
                request.update(
                    temperature=sampling["temperature"],
                    top_p=sampling["top_p"],
                    seed=sampling["seed"] + len(rows),
                )
            try:
                row = judge(language, ask(request))
            except Exception as error:  # noqa: BLE001 - a failed or malformed answer is recorded, not a pass
                row = judge(language, error)
            if sampling is not None:
                row["seed"] = request["seed"]
            rows.append(row)
    verdicts = {row["verdict"] for row in rows}
    verdict = (
        "fail"
        if "fail" in verdicts
        else "pass"
        if verdicts == {"pass"}
        else "inconclusive"
    )
    result = {"runs": rows, "verdict": verdict, "passed": verdict == "pass"}
    if sampling is not None:
        result["sampling"] = {**sampling, "repeats": repeats}
    return result

"""Read the KV pool as the running engine reports it, without a runtime patch.

vLLM's boot line "GPU KV cache size: N tokens" is max_concurrency x max_model_len
for this hybrid model (MLA, IndexPool tail, KDA state groups, MTP draft), not the
number of conversation tokens the prefix cache can hold. This module separates
the two and only estimates cached-conversation capacity when every group's spec
kind is one it models; otherwise the figure is withheld, not guessed.
"""

import math
import re

STOCK = re.compile(
    r"GPU KV cache size: ([\d,]+) tokens, Maximum concurrency for ([\d,]+) tokens "
    r"per request: ([\d.]+)x"
)
GROUPS = re.compile(r"kv cache group sizes \[([^\]]*)\]")
SCHEDULER_BLOCK = re.compile(r"kv lcm block sizes (\d+)")
CACHE_INFO = re.compile(r"vllm:cache_config_info\{([^}]*)\}")
LABEL = re.compile(r'(\w+)="((?:[^"\\]|\\.)*)"')
MEANING = (
    "The stock 'GPU KV cache size' line is max_concurrency x max_model_len: how "
    "many maximum-length requests the pool holds at once, in token units. It is "
    "not the number of cached conversation tokens."
)

def from_logs(text):
    """Take the last boot's lines; a container log may hold one boot only."""
    result = {}
    stock = STOCK.findall(text)
    if stock:
        tokens, length, concurrency = stock[-1]
        result["stock"] = {
            "kv_cache_size_tokens": int(tokens.replace(",", "")),
            "max_model_len": int(length.replace(",", "")),
            "max_concurrency": float(concurrency),
        }
    groups = GROUPS.findall(text)
    if groups:
        result["group_block_sizes"] = [
            int(item) for item in groups[-1].split(",") if item.strip()
        ]
    block = SCHEDULER_BLOCK.findall(text)
    if block:
        result["scheduler_block_size"] = int(block[-1])
    return result

def from_metrics(text):
    """CacheConfig fields as the API server exports them; 'None' stays None."""
    match = CACHE_INFO.search(text)
    if not match:
        return {}
    labels = dict(LABEL.findall(match.group(1)))
    result = {}
    for key, cast in (
        ("num_gpu_blocks", int),
        ("block_size", int),
        ("kv_cache_size_tokens", int),
        ("kv_cache_max_concurrency", float),
    ):
        value = labels.get(key)
        if value is None or value == "None":
            continue
        try:
            result[key] = cast(value)
        except ValueError:
            continue
    return result

def group_cost(group, tokens, retention_interval):
    """Blocks one cached T-token conversation keeps in this group, or a reason.

    Dense retention with block-aligned hits: attention groups keep every block,
    a KDA (mamba) group keeps one checkpoint per block only when retention is
    dense (interval None), and the private IndexPool tail ring publishes nothing.
    """
    kind, block = group["kind"], group["block_size"]
    if kind in ("FullAttentionSpec", "MLAAttentionSpec"):
        return math.ceil(tokens / block)
    if kind == "MambaSpec":
        if retention_interval is None:
            return math.ceil(tokens / block)
        return f"mamba retention interval {retention_interval} is not modelled"
    if "Kpool" in kind or "Tail" in kind:
        return 0
    return f"{kind} is not modelled"

def conversation_estimate(layout, lengths, retention_interval):
    groups = layout["groups"]
    usable = layout["num_blocks"] - 1  # block id 0 is the null block
    rows = []
    for tokens in lengths:
        costs = [group_cost(group, tokens, retention_interval) for group in groups]
        withheld = [cost for cost in costs if isinstance(cost, str)]
        if withheld:
            return {"withheld": sorted(set(withheld))}
        blocks = sum(costs)
        rows.append(
            {
                "tokens": tokens,
                "blocks": blocks,
                "per_group": costs,
                "conversations": usable // blocks if blocks else None,
            }
        )
    return {
        "usable_blocks": usable,
        "assumptions": (
            "nothing running, dense retention, block-aligned hits; a running "
            "request also holds its tail ring and any partial block"
        ),
        "rows": rows,
    }

def summarize(profile, logs, metrics, layout=None):
    """logs: head container log text; metrics: /metrics text; layout: rank 0's
    apc_cache_layout when the profile loads the LPA worker extension."""
    boot = from_logs(logs)
    info = from_metrics(metrics)
    result = {"meaning": MEANING, **boot, "cache_config_info": info}
    concurrency = boot.get("stock", {}).get("max_concurrency") or info.get(
        "kv_cache_max_concurrency"
    )
    num_blocks = info.get("num_gpu_blocks")
    if layout is not None:
        num_blocks = layout["num_blocks"]
    result["num_gpu_blocks"] = num_blocks
    if concurrency:
        result["full_length_requests_that_fit"] = math.floor(concurrency)
        if num_blocks:
            result["blocks_per_max_length_request"] = round(num_blocks / concurrency)
    if layout is None:
        result["cached_conversations"] = {
            "withheld": [
                "group spec kinds are exported by the LPA worker extension only "
                "(lpa.enabled profiles); block widths alone do not say which "
                "groups publish to the prefix cache"
            ]
        }
    else:
        limit = profile["context"]["max_model_len"]
        lengths = sorted(
            {length for length in (16384, 65536, limit) if length <= limit}
        )
        result["cached_conversations"] = conversation_estimate(
            layout, lengths, layout.get("retention_interval")
        )
    return result

"""Cold/warm prefix-cache correctness gate on one long shared prefix.

``tools/check_prefix_cache.py`` shows whether a repeat hits the cache; this
checks whether what the hit restores is right. N short tasks share one long
synthetic log whose answers are fixed by its seed. They are asked in parallel
under a fresh ``cache_salt`` (cold: the first request computes the prefix, the
others may read it while or after it is written), then again under the same
salt (warm: every request should hit), and every answer is checked against the
log. A task the cold pass answered and the warm pass got wrong is read as a
broken prefix cache; a warm pass that reports no cached tokens did not test
the cache and never passes.

Adapted from knapcio/GLM-5.3-Flash-4x-DGX-Spark-TP4, ``bench/prefix_scan.py``
at 770d1153062aa916b06591411c61d5c593ea0f03 (MIT, Copyright (c) 2026 knapcio;
notice in LICENSES/knapcio-MIT.txt): the record format, the lookup and quote
tasks and their parsing. Local changes: exact answers at temperature 0
instead of sampled rounds, the server's own chat tokenization for the length,
a paired cold/warm verdict, and no logprob drift, degenerate-run or block-phase
checks.

Nothing here talks to a server; the caller passes ``ask`` and ``count_tokens``.
"""

import random
import re
from concurrent.futures import ThreadPoolExecutor

# Upper bounds on the prompt, in the server's chat tokens. Long: the ~99K-token
# log that reproduced knapcio's issue #2. Short: a length measured to restore
# 9,216 tokens on the 4,608-token block (docs/server-configuration.md); below
# two blocks a repeat restores nothing.
LENGTHS = {"long": 99_000, "short": 14_025}
SEED = 7  # knapcio's default; the log is a function of it.
# The lookups near the end reach 60 records back.
MIN_RECORDS = 64
# knapcio's estimate of one record's tokens; only the first sizing guess.
TOKENS_PER_RECORD = 32
ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ"
STATES = ("idle", "dead", "drained", "leased", "stale")
RECORD = (
    "Record {:05d} host=node-{:02d} state={} retries={} at t={}s ref={};"
    " lease held then released."
)
QUOTED = re.compile(r"Record \d{5} host=[^\n]*?released\.")
LOOKED_UP = re.compile(r"Record\s*(\d{1,5})\s*[:=\-]?\s*(?:ref=)?\s*([A-Z]{5})\b")

class Prefix:
    """``records`` log lines; each ref code is random, so a right one was read."""

    def __init__(self, records, seed):
        draw = random.Random(seed)
        self.seed = seed
        self.codes = [
            "".join(draw.choice(ALPHABET) for _ in range(5)) for _ in range(records)
        ]
        self.lines = [
            RECORD.format(
                i,
                i % 29,
                STATES[draw.randrange(len(STATES))],
                draw.randrange(6),
                7 * i,
                self.codes[i],
            )
            for i in range(records)
        ]
        self.text = "\n".join(self.lines)

def build_prefix(records, seed):
    return Prefix(records, seed)

def tasks(prefix):
    """Four lookups spread over the log, including its end, and two quotes."""
    n = len(prefix.lines)

    def at(share):
        return int(share * n)

    rows = [
        {
            "kind": "lookup",
            "targets": (a, b),
            "question": f"Give the ref code of Record {a:05d} and of Record {b:05d}, "
            "one per line exactly as 'Record N: CODE'. Output only those two lines.",
        }
        for a, b in (
            (at(0.10), at(0.35)),
            (at(0.60), at(0.85)),
            (n - 60, n - 25),
            (n - 40, n - 8),
        )
    ]
    middle = at(0.5)
    rows.append(
        {
            "kind": "quote",
            "targets": (middle, middle + 1),
            "question": f"Quote verbatim, exactly as they appear, the lines for "
            f"Record {middle:05d} and Record {middle + 1:05d}, one per line.",
        }
    )
    rows.append(
        {
            "kind": "quote",
            "targets": (n - 3, n - 2, n - 1),
            "question": "Quote verbatim the last three lines of the log, one per line.",
        }
    )
    return rows

def request(prefix, task, salt):
    return {
        "messages": [
            {"role": "user", "content": prefix.text + "\n\n" + task["question"]}
        ],
        "temperature": 0,
        "cache_salt": salt,
    }

def answer(prefix, task):
    """The one correct reply."""
    if task["kind"] == "lookup":
        return "\n".join(f"Record {i:05d}: {prefix.codes[i]}" for i in task["targets"])
    return "\n".join(prefix.lines[i] for i in task["targets"])

def verify(prefix, task, content):
    """Correct means every asked fact is present and nothing stated is false."""
    known = set(prefix.lines)
    mismatches = [line for line in QUOTED.findall(content) if line not in known]
    found = {}
    for number, code in LOOKED_UP.findall(content):
        index = int(number)
        found[index] = code
        if index >= len(prefix.codes):
            mismatches.append(f"Record {index:05d}: {code} (no such record)")
        elif code != prefix.codes[index]:
            mismatches.append(
                f"Record {index:05d}: {code} (truth {prefix.codes[index]})"
            )
    if task["kind"] == "lookup":
        present = all(found.get(i) == prefix.codes[i] for i in task["targets"])
    else:
        present = all(prefix.lines[i] in content for i in task["targets"])
    return {"correct": present and not mismatches, "mismatches": mismatches}

def fit_prefix(count_tokens, limit, seed):
    """The longest log whose every task prompt stays within ``limit`` tokens."""

    def longest(records):
        prefix = build_prefix(records, seed)
        return prefix, max(count_tokens(request(prefix, t, "")) for t in tasks(prefix))

    records = max(MIN_RECORDS, limit // TOKENS_PER_RECORD)
    prefix, used = longest(records)
    records = max(1, records * limit // used)
    prefix, used = longest(records)
    while used > limit and records > 1:
        records = max(1, min(records - 1, records * limit // used))
        prefix, used = longest(records)
    if used > limit or records < MIN_RECORDS:
        raise ValueError(f"{limit} tokens is too short for {MIN_RECORDS} records")
    return prefix, used

"""Post-readiness request ladder that compiles kernels before interactive use.

The pinned launch disables vLLM's own JIT warmup, so a prompt shape seen for the
first time compiles while serving. On this kit that compile burst once pushed the
head below its memory reserve (docs/vision.md). The rungs come from the shapes
that were observed compiling during serving: a short text turn (also at the
checkpoint's sampling), a tool call, one image and the longest prompt the
operator intends to serve. A counting canary closes the ladder and judges
whether the launch decodes correctly (docs/operations.md).
"""

import base64
import math
import re
import struct
import zlib

from .server_config import optional

COMPILED = re.compile(r"JIT compilation during inference: (.+?)\. This causes")
ANSWER_TOKENS = 32  # Enough decode steps to reach the sampling kernels.
LONG_LINE = "warmup line {index}.\n"
# The last rung doubles as a correctness canary (upstream MiaAI-Lab recipe #268):
# a launch that answers /health but decodes garbage fails its switch instead of
# serving. Counting to 80 is checkable exactly and long enough that the MTP
# check judges from this rung alone, whatever other rungs a profile runs: on the
# 1.19.0 pair it took 168 tokens and drafted 126 at effort low, 207 and 162 at
# max (records/20260928-upstream-review/obs268), so 256 answers either way.
CANARY_COUNT = 80
CANARY_TOKENS = 256
# Zero accepted drafts only counts over at least this many drafted tokens, as
# upstream's GLM53_WARMUP_CANARY_MIN_DRAFTS.
MIN_DRAFTS = 64
SPEC_METRICS = {
    "vllm:spec_decode_num_draft_tokens_total": "num_draft_tokens",
    "vllm:spec_decode_num_accepted_tokens_total": "num_accepted_tokens",
}

def parse_metrics(text, names):
    """Sum each named Prometheus sample over its label sets; absent names are omitted."""
    totals = {}
    for line in text.splitlines():
        if not line or line.startswith("#"):
            continue
        head, _, value = line.rpartition(" ")
        name = head.split("{", 1)[0]
        if name in names:
            try:
                totals[name] = totals.get(name, 0.0) + float(value)
            except ValueError:
                continue
    return totals

def spec_counters(metrics):
    """The draft and accepted totals from a Prometheus /metrics text."""
    return {SPEC_METRICS[k]: v for k, v in parse_metrics(metrics, SPEC_METRICS).items()}

def compiled_kernels(logs):
    """Kernel names the jit_monitor reported as compiled while serving."""
    return set(COMPILED.findall(logs))

def png_data_url(width=672, height=336, rgb=(255, 140, 0)):
    """A solid-colour PNG built with the standard library; no image dependency.

    The default is the size of the synthetic image the 200K vision checks sent
    (records/20260915-vision-200k), which the processor accepted as 288 tokens.
    """

    def chunk(kind, payload):
        body = kind + payload
        return (
            struct.pack(">I", len(payload))
            + body
            + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)
        )

    row = b"\x00" + bytes(rgb) * width
    png = (
        b"\x89PNG\r\n\x1a\n"
        + chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0))
        + chunk(b"IDAT", zlib.compress(row * height, 9))
        + chunk(b"IEND", b"")
    )
    return "data:image/png;base64," + base64.b64encode(png).decode("ascii")

def long_prompt(target_tokens, limit_tokens, count_tokens, sample_lines=256):
    """Build a prompt of about target_tokens, never above limit_tokens.

    count_tokens(text) asks the running server's tokenizer, so the estimate
    uses the served chat template rather than a guessed tokens-per-word ratio.
    """
    if target_tokens < 1 or target_tokens > limit_tokens:
        raise ValueError("Long rung must be positive and fit the context")

    def build(lines):
        text = "".join(LONG_LINE.format(index=i) for i in range(lines))
        return text, count_tokens(text)

    sample = "".join(LONG_LINE.format(index=i) for i in range(sample_lines))
    lines = max(1, math.ceil(target_tokens * sample_lines / count_tokens(sample)))
    text, tokens = build(lines)
    # A line costs more once its index grows a digit, so a short sample
    # under-counts: measured 82,006 tokens for a 65,536 target on the reference
    # tokenizer. Rescale against the real count instead of trusting the sample.
    for _ in range(4):
        if not tokens or abs(tokens - target_tokens) <= target_tokens // 50:
            break
        scaled = max(1, int(lines * target_tokens / tokens))
        if scaled == lines:
            break
        lines = scaled
        text, tokens = build(lines)
    while tokens > limit_tokens and lines > 1:
        lines = max(1, math.floor(lines * limit_tokens / tokens) - 1)
        text, tokens = build(lines)
    return text, tokens

def rungs(profile):
    """Ordered (name, request) pairs; the long rung is built at run time."""
    ladder = [
        (
            "text",
            {
                "messages": [{"role": "user", "content": "Reply with the word ready."}],
                "max_tokens": ANSWER_TOKENS,
            },
        ),
        (
            # A client that sends no temperature (ZCode) gets the checkpoint's
            # generation_config, temperature 1.0 and top_p 0.95; its first such
            # request compiled three _topp_sb_* kernels, which the other rungs,
            # sent at the profile's temperature 0, never reach (2026-09-28).
            "sampled",
            {
                "messages": [{"role": "user", "content": "Reply with the word ready."}],
                "temperature": 1.0,
                "top_p": 0.95,
                "max_tokens": ANSWER_TOKENS,
            },
        ),
        (
            "tool",
            {
                "messages": [
                    {
                        "role": "user",
                        "content": "What time is it in Tokyo? Use the tool.",
                    }
                ],
                "tools": [
                    {
                        "type": "function",
                        "function": {
                            "name": "current_time",
                            "description": "Current time in a city",
                            "parameters": {
                                "type": "object",
                                "properties": {"city": {"type": "string"}},
                                "required": ["city"],
                            },
                        },
                    }
                ],
                "tool_choice": "auto",
                "max_tokens": ANSWER_TOKENS,
            },
        ),
    ]
    if optional(profile, "runtime", "vision"):
        ladder.append(
            (
                "image",
                {
                    "messages": [
                        {
                            "role": "user",
                            "content": [
                                {"type": "text", "text": "Name the colour."},
                                {
                                    "type": "image_url",
                                    "image_url": {"url": png_data_url()},
                                },
                            ],
                        }
                    ],
                    "max_tokens": ANSWER_TOKENS,
                },
            )
        )
    if optional(profile, "generation", "warmup_long_tokens"):
        ladder.append(("long", None))
    ladder.append(
        (
            "canary",
            {
                "messages": [
                    {
                        "role": "user",
                        "content": f"Count from 1 to {CANARY_COUNT}, separated by "
                        "single spaces. Reply with the numbers only.",
                    }
                ],
                "temperature": 0,
                "reasoning_effort": "low",
                "max_tokens": CANARY_TOKENS,
            },
        )
    )
    return ladder
